// ============================================================
// FUNÇÕES UTILITÁRIAS
// ============================================================
function isFileType(i, e) { return FILE_TYPES[e] && FILE_TYPES[e].includes(i?.toLowerCase()); }
function getFileIcon(i) {
    const e = i?.toLowerCase();
    return isFileType(e, "video") ? '<i class="bi bi-camera-video-fill text-primary"></i>' :
           isFileType(e, "audio") ? '<i class="bi bi-music-note-beamed text-pink"></i>' :
           isFileType(e, "image") ? '<i class="bi bi-image text-success"></i>' :
           isFileType(e, "archive") ? '<i class="bi bi-file-earmark-zip-fill text-warning"></i>' :
           e === "pdf" ? '<i class="bi bi-file-earmark-pdf-fill text-danger"></i>' :
           isFileType(e, "code") ? '<i class="bi bi-code-slash text-purple"></i>' : '<i class="bi bi-file-earmark"></i>';
}
function getDocumentHeight() { const i = document; return Math.max(i.body.scrollHeight, i.documentElement.scrollHeight); }
function getQueryVariable(i) {
    const t = window.location.search.substring(1).split("&");
    for (let n = 0; n < t.length; n++) { const a = t[n].split("="); if (a[0] == i) return a.slice(1).join("="); }
    return false;
}
function escHtml(i) { return String(i || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#x27;"); }
function trimChar(i, e) { return e ? i.replace(new RegExp("^\\" + e + "+|\\" + e + "+$", "g"), "") : i.trim(); }
function applyTheme(i) {
    document.documentElement.setAttribute("data-bs-theme", i);
    const e = document.getElementById("theme-icon");
    e && (e.className = i === "dark" ? "bi bi-moon-stars" : "bi bi-sun");
}
function toggleTheme() {
    const e = (document.documentElement.getAttribute("data-bs-theme") || "dark") === "dark" ? "light" : "dark";
    localStorage.setItem("gdi-theme", e);
    applyTheme(e);
    GDIUserSystem.updatePreferences({theme: e});
}
function sleep(i) { return new Promise(e => setTimeout(e, i)); }
function formatFileSize(i) {
    const e = Number(i);
    return isNaN(e) || e < 0 ? "" : e >= 1073741824 ? (e / 1073741824).toFixed(2) + " GB" : e >= 1048576 ? (e / 1048576).toFixed(2) + " MB" : (e / 1024).toFixed(2) + " KB";
}
function formatDateTime(i) { return i ? new Date(i).toLocaleString() : ""; }
const utc2delhi = formatDateTime;
function formatTime(seconds) {
    const h = Math.floor(seconds / 3600), m = Math.floor((seconds % 3600) / 60), s = Math.floor(seconds % 60);
    return h > 0 ? `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}` : `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

// ============================================================
// INICIALIZAÇÃO DA APLICAÇÃO & LAYOUT
// ============================================================
function init() {
    const UI = window.UI || {};
    document.siteName = $("title").html();
    const html = `
    <div id="nav"></div>
    <div id="content" style="padding-top:76px; padding-bottom:100px;"></div>
    <div id="gdi-toast-container"></div>
    <footer class="text-center py-4 text-muted" style="font-size:13px;border-top:1px solid var(--gdi-border);">
      <span>&copy; ${new Date().getFullYear()} ${UI.company_name || 'Drive'} &middot; Plataforma de Estudos Acadêmicos</span>
    </footer>`;
    $("body").html(html);
}

function title(i) {
    try { i = decodeURI(i); } catch {}
    const e = window.current_drive_order || 0, t = (window.drive_names && window.drive_names[e]) || "Drive";
    i = i.replace(`/${e}:`, "");
    const n = window.MODEL || {};
    n.is_search_page ? $("title").html(`${t} - Busca: ${n.q || ""}`) : $("title").html(`${t} - ${i}`);
}

function nav(i) {
    const e = window.MODEL || {}, t = window.current_drive_order || 0, n = (window.drive_names && window.drive_names[t]) || "Drive", a = window.drive_names || [], UI = window.UI || {};
    let l = "";
    a.forEach((r, p) => { l += `<li><a class="dropdown-item${p === t ? " active" : ""}" href="/${p}:/"><i class="bi bi-folder2-open me-2"></i>${r}</a></li>`; });
    
    const navBarHtml = `
    <nav class="gdi-nav">
      <div class="gdi-nav-inner">
        <a class="gdi-logo" href="/${t}:/"><i class="bi bi-mortarboard-fill"></i> <span>${UI.logo_link_name || 'Academia'}</span></a>
        ${(e.root_type === undefined || e.root_type < 2) ? `<div class="d-none d-md-block"><form class="gdi-search-form" method="get" action="/${t}:search"><input class="gdi-search-input" name="q" type="search" placeholder="Pesquisar aulas e materiais…" value="${escHtml(e.q || '')}"><i class="bi bi-search"></i></form></div>` : ''}
        <div class="d-flex align-items-center gap-2">
          <div class="dropdown">
            <button class="gdi-btn gdi-btn-ghost dropdown-toggle" type="button" data-bs-toggle="dropdown">${escHtml(n)}</button>
            <ul class="dropdown-menu dropdown-menu-end shadow">${l}</ul>
          </div>
          <button class="gdi-btn gdi-btn-ghost" onclick="toggleTheme()" title="Alternar Tema"><i class="bi bi-moon-stars" id="theme-icon"></i></button>
        </div>
      </div>
    </nav>`;
    $("#nav").html(navBarHtml);
    applyTheme(localStorage.getItem("gdi-theme") || "dark");
}

function render(i) {
    if (i.indexOf("?") >= 0) i = i.substr(0, i.indexOf("?"));
    title(i); nav(i);
    const e = /\/\d+:$/g;
    if (i.includes("/fallback")) {
        const t = getQueryVariable("a"), n = decodeURIComponent(getQueryVariable("id") || "");
        return t ? fallback(n, true) : list(null, n, true);
    } else if (window.MODEL?.is_search_page) {
        render_search_result_list();
    } else if (i.match(e) || i.slice(-1) == "/") {
        list(i);
    } else {
        file(i);
    }
}

// ============================================================
// LISTAGEM, BANNER E MARCAÇÃO DE AULAS
// ============================================================
function requestListPath(i, e, t, n, a = 3, c = false) {
    const l = { id: e.id || "", type: "folder", password: e.password || "", page_token: e.page_token || "", page_index: e.page_index || 0 };
    $("#update").show();
    $("#update").html('<div class="alert alert-info py-2">Carregando conteúdos...</div>');
    c && (i = "/0:fallback");
    
    async function o(s) {
        try {
            const r = await fetch(c ? "/0:fallback" : i, { method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify(l) });
            if (!r.ok) throw new Error("Erro " + r.status);
            const p = await r.json();
            if (p && p.error && p.error.code === 401) { $("#update").hide(); askPassword(i); }
            else if (p && p.data) { t(p, i, l); $("#update").hide(); }
        } catch (r) {
            if (s > 0) { await sleep(2000); await o(s - 1); }
            else { $("#update").html('<div class="alert alert-danger">Falha ao carregar dados.</div>'); $("#spinner").remove(); }
        }
    }
    o(a);
}

function list(i, e = "", t = false) {
    const n = window.location.pathname, a = trimChar(n, "/").split("/");
    let c = "/", l = '<li><a href="/">Início</a></li><li class="gdi-bc-sep">/</li>';
    if (a.length > 1) {
        for (const p in a) {
            const g = a[p];
            let f; try { f = decodeURIComponent(g); } catch { f = g; }
            f = f.replace(/\//g, "%2F");
            const u = f.match(/^(\d+):$/), h = u && window.drive_names && window.drive_names[+u[1]] || f, m = h.length > 22 ? h.slice(0, 18) + "…" : h;
            c += g + "/";
            if (!m) break;
            if (Number(p) === a.length - 1) l += `<li class="gdi-bc-cur">${escHtml(m)}</li>`;
            else l += `<li><a href="${c}">${escHtml(m)}</a></li><li class="gdi-bc-sep">/</li>`;
        }
    }
    
    const d = `
    <div class="gdi-wrap">
      <div id="update"></div>
      <div id="continue-watching-container"></div>
      <div class="gdi-breadcrumb-wrap"><ol class="gdi-bc">${l}</ol></div>
      <div class="gdi-panel">
        <div class="p-3 border-bottom border-secondary">
          <input id="folder-filter" class="gdi-search-input" style="width:100%;max-width:400px;" type="search" placeholder="Filtrar arquivos nesta pasta…" autocomplete="off">
        </div>
        <div class="gdi-list-header">
          <span></span><span>Nome do Arquivo / Aula</span><span>Tamanho</span><span>Modificado</span><span class="text-end">Ações / Conclusão</span>
        </div>
        <div id="list"></div>
        <div id="count" class="p-3 text-muted text-center" style="font-size:13px;"></div>
      </div>
    </div>`;
    
    $("#content").html(d);
    renderContinueWatchingBanner();
    
    const o = localStorage.getItem("password" + i);
    $("#list").html('<div class="text-center py-5" id="spinner"><div class="spinner-border text-primary" role="status"></div></div>');
    
    function s(p, g, f) {
        $("#spinner").remove();
        t ? append_files_to_fallback_list(g, p.data.files) : append_files_to_list(g, p.data.files);
    }
    t ? requestListPath(i, {id: e, password: o}, s, null, 3, true) : requestListPath(i, {password: o}, s, null);
    
    document.getElementById("folder-filter")?.addEventListener("input", function() {
        const val = this.value.toLowerCase();
        document.querySelectorAll("#list .gdi-row").forEach(row => {
            row.style.display = (row.dataset.name || "").includes(val) ? "" : "none";
        });
    });
}

function renderContinueWatchingBanner() {
    const history = GDIUserSystem.getContinueWatching();
    const container = document.getElementById('continue-watching-container');
    if (!container || history.length === 0) return;
    
    let html = `
    <div class="gdi-panel p-4 mb-4" style="background:linear-gradient(135deg, rgba(59,130,246,0.08), rgba(139,92,246,0.05)); border:1px solid rgba(59,130,246,0.2);">
        <h5 class="mb-3 fw-bold" style="font-size:15px;"><i class="bi bi-play-circle-fill text-primary me-2"></i>Continuar Assistindo</h5>
        <div class="d-flex gap-3 overflow-x-auto pb-2" style="scrollbar-width:thin;">`;
    history.forEach(item => {
        const pct = Math.round((item.progress || 0) * 100);
        html += `
        <div class="p-3 rounded flex-shrink-0" style="width:240px;background:var(--gdi-surface);border:1px solid var(--gdi-border);cursor:pointer;" onclick="window.location.href='${item.url}'">
            <div class="fw-semibold text-truncate mb-2" style="font-size:13px;" title="${escHtml(item.name)}">${escHtml(item.name)}</div>
            <div class="progress mb-2" style="height:5px;background:rgba(255,255,255,0.1);"><div class="progress-bar bg-primary" style="width:${pct}%"></div></div>
            <div class="d-flex justify-content-between text-muted" style="font-size:11px;"><span>Progresso</span><span class="text-primary fw-bold">${pct}%</span></div>
        </div>`;
    });
    html += `</div></div>`;
    container.innerHTML = html;
}

function append_files_to_list(i, e) {
    const UI = window.UI || {}, t = $("#list");
    let c = "", totalSize = 0, fileCount = 0;
    for (const o in e) {
        const s = e[o];
        const r = encodeURIComponent(s.name).replace(/\//g, "%2F") + "/", p = i + r.replace(/#/g, "%23").replace(/\?/g, "%3F");
        s.modifiedTime = utc2delhi(s.modifiedTime);
        if (s.mimeType == "application/vnd.google-apps.folder") {
            c += `<a href="${p}" class="gdi-row" data-name="${escHtml(s.name.toLowerCase())}"><span class="gdi-row-icon"><i class="bi bi-folder-fill text-warning"></i></span><span class="gdi-row-name">${escHtml(s.name)}</span><span class="text-muted">-</span><span class="text-muted" style="font-size:12px;">${s.modifiedTime}</span><span class="text-end"><i class="bi bi-chevron-right text-muted"></i></span></a>`;
        } else {
            totalSize += Number(s.size || 0); fileCount++;
            const f = s.fileExtension, u = UI.second_domain_for_dl ? UI.downloaddomain + s.link : window.location.origin + s.link;
            const viewUrl = i + encodeURIComponent(s.name) + "?a=view";
            const isCompleted = GDIUserSystem.currentUser?.completedLessons?.[s.id] ? 'checked' : '';
            c += `<div class="gdi-row" data-name="${escHtml(s.name.toLowerCase())}"><span class="gdi-row-icon">${getFileIcon(f)}</span><span class="gdi-row-name"><a href="${viewUrl}" class="text-decoration-none text-reset" title="${escHtml(s.name)}">${escHtml(s.name)}</a></span><span class="text-muted" style="font-size:12px;">${formatFileSize(s.size)}</span><span class="text-muted" style="font-size:12px;">${s.modifiedTime}</span><span class="text-end d-flex align-items-center justify-content-end gap-2"><input class="form-check-input" type="checkbox" ${isCompleted} onchange="toggleLessonComplete('${s.id}', this)" title="Marcar concluída" style="cursor:pointer;"><a class="gdi-btn gdi-btn-ghost py-1 px-2" href="${u}" download title="Baixar"><i class="bi bi-download"></i></a></span></div>`;
        }
    }
    t.append(c);
    const countEl = document.getElementById("count");
    if (countEl) countEl.innerHTML = `${fileCount} itens (${formatFileSize(totalSize)})`;
}

function toggleLessonComplete(fileId, checkbox) {
    const user = GDIUserSystem.currentUser;
    if (!user) return;
    if (!user.completedLessons) user.completedLessons = {};
    user.completedLessons[fileId] = checkbox.checked;
    GDIUserSystem.saveUser(user);
    showToast(checkbox.checked ? 'Aula concluída! 🏆' : 'Aula marcada como pendente.');
}

function append_files_to_fallback_list(i, e) { append_files_to_list(i, e); }
function askPassword(i) {
    $("#spinner").remove();
    const e = prompt("Digite a senha de acesso:", "");
    e ? (localStorage.setItem("password" + i, e), list(i)) : history.go(-1);
}

// ============================================================
// VISUALIZADORES E PLAYER DE VÍDEO COM PLAYLIST E ANOTAÇÕES
// ============================================================
async function fallback(i, e) {
    if (e) {
        const t = await getCookie("root_id") || "";
        $("#content").html('<div class="text-center py-5"><div class="spinner-border text-primary" role="status"></div></div>');
        fetch("/0:fallback", { method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({id: i}) })
            .then(n => n.json()).then(n => dispatchFileView(n, t)).catch(n => $("#content").html(renderErrorCard(n)));
    } else { list(i, true); }
}

async function file(i) {
    const e = await getCookie("root_id") || "";
    $("#content").html('<div class="text-center py-5"><div class="spinner-border text-primary" role="status"></div></div>');
    fetch("", { method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({path: i}) })
        .then(t => t.json()).then(t => dispatchFileView(t, e)).catch(t => $("#content").html(renderErrorCard(t)));
}

function dispatchFileView(i, e) {
    const UI = window.UI || {}, t = i.mimeType, n = i.fileExtension;
    if (t === "application/vnd.google-apps.folder") { window.location.href = window.location.pathname + "/"; return; }
    const a = i.name, l = formatFileSize(i.size), d = UI.second_domain_for_dl ? UI.downloaddomain + i.link : window.location.origin + i.link, o = i.id;
    
    if (t && GDOC_TYPES[t]) file_workspace(a, l, t, d);
    else if (FILE_TYPES.video.includes(n) || t?.includes("video")) file_video(a, encodeURIComponent(a), l, i.thumbnailLink || UI.poster, d, t, o);
    else if (FILE_TYPES.audio.includes(n) || t?.includes("audio")) file_audio(a, encodeURIComponent(a), l, d);
    else if (FILE_TYPES.image.includes(n) || t?.includes("image")) file_image(a, encodeURIComponent(a), l, d);
    else if (n === "pdf" || t?.includes("pdf")) file_pdf(a, encodeURIComponent(a), l, d);
    else if (FILE_TYPES.code.includes(n)) file_code(a, encodeURIComponent(a), l, i.size, d, n);
    else file_others(a, encodeURIComponent(a), l, d);
}

function renderErrorCard(i) { return `<div class="gdi-wrap"><div class="gdi-viewer-card text-center py-5"><h4>Erro</h4><p class="text-muted">${escHtml(String(i))}</p><a href="/" class="gdi-btn gdi-btn-primary mt-3">Início</a></div></div>`; }
function renderDownloadButtons(i) { return `<div class="d-flex justify-content-between align-items-center mt-4 pt-3 border-top border-secondary"><span class="text-muted text-truncate" style="font-size:12px;max-width:50%;">${escHtml(i)}</span><a href="${i}" class="gdi-btn gdi-btn-primary" download><i class="bi bi-download"></i> Baixar</a></div>`; }
function showToast(i) {
    let e = document.getElementById("gdi-toast-container");
    if (!e) { e = document.createElement("div"); e.id = "gdi-toast-container"; document.body.appendChild(e); }
    const t = document.createElement("div"); t.className = "gdi-toast";
    t.innerHTML = `<i class="bi bi-check-circle-fill text-success"></i> <span>${i}</span>`;
    e.appendChild(t);
    setTimeout(() => { t.remove(); }, 3000);
}

function _viewerCard(icon, title, meta, body, footer) {
    return `<div class="gdi-wrap"><div class="gdi-breadcrumb-wrap mb-3"><ol class="gdi-bc">${generateBreadcrumb(window.location.pathname)}</ol></div><div class="gdi-viewer-card"><div class="d-flex align-items-center gap-3 mb-4 pb-3 border-bottom border-secondary"><div style="font-size:26px;">${icon}</div><div><h4 class="mb-1" style="font-size:16px;font-weight:600;">${escHtml(title)}</h4><span class="text-muted" style="font-size:12px;">${escHtml(meta)}</span></div></div><div>${body}</div>${footer || ''}</div></div>`;
}
function generateBreadcrumb(i) {
    const e = i.split("/"); let t = "", n = "";
    for (let a = 0; a < e.length; a++) {
        let c = e[a]; n += (a === 0 ? "" : "/") + c;
        const l = a === e.length - 1; let d = decodeURIComponent(c) || "Home";
        if (l) t += `<li class="gdi-bc-cur">${escHtml(d)}</li>`;
        else t += `<li><a href="${n ? n + "/" : "/"}">${escHtml(d)}</a></li><li class="gdi-bc-sep">/</li>`;
    }
    return t;
}

function file_others(i, e, t, n) { $("#content").html(_viewerCard('<i class="bi bi-file-earmark"></i>', i, t, '<p class="text-muted">Sem visualização prévia.</p>', renderDownloadButtons(n))); }
function file_workspace(i, e, t, n) { $("#content").html(_viewerCard('<i class="bi bi-file-earmark-text"></i>', i, e, '<p class="text-muted">Documento do Google Workspace.</p>', renderDownloadButtons(n))); }
function file_code(i, e, t, n, a, c) {
    $("#content").html(_viewerCard('<i class="bi bi-code-slash"></i>', i, t, '<pre class="p-3 rounded" style="background:var(--gdi-bg)"><code id="editor">Carregando...</code></pre>', renderDownloadButtons(a)));
    $.get(a, res => $("#editor").text(res));
}
function file_audio(i, e, t, n) { $("#content").html(_viewerCard('<i class="bi bi-music-note-beamed text-pink"></i>', i, t, `<audio controls autoplay style="width:100%;margin:20px 0;"><source src="${n}"></audio>`, renderDownloadButtons(n))); }
function file_image(i, e, t, n) { $("#content").html(_viewerCard('<i class="bi bi-image"></i>', i, t, `<div class="text-center"><img src="${n}" class="img-fluid rounded" style="max-height:600px;"></div>`, renderDownloadButtons(n))); }
function file_pdf(i, e, t, n) { $("#content").html(_viewerCard('<i class="bi bi-file-earmark-pdf"></i>', i, t, `<iframe src="${n}" style="width:100%;height:750px;border:none;"></iframe>`, renderDownloadButtons(n))); }

// ============================================================
// PLAYER DE VÍDEO COMPLETO (COM PLAYLIST LATERAL E ANOTAÇÕES)
// ============================================================
function file_video(i, e, t, n, a, c, fileId) {
    const playerHtml = `<video id="player" playsinline controls autoplay style="width:100%;max-height:550px;background:#000;"><source src="${a}" type="video/mp4"></video>`;
    
    const notesPanel = `
    <div class="mt-4 pt-3 border-top border-secondary">
        <h5 class="mb-3" style="font-size:15px;"><i class="bi bi-journal-text text-primary me-2"></i>Anotações da Aula</h5>
        <div class="d-flex gap-2 mb-3">
            <input id="gdi-note-input" type="text" class="form-control bg-dark text-light border-secondary" placeholder="Anotar no minuto atual..." onkeypress="if(event.key==='Enter')addVideoNote('${fileId}')">
            <button class="gdi-btn gdi-btn-primary" onclick="addVideoNote('${fileId}')"><i class="bi bi-plus-lg"></i></button>
        </div>
        <div id="gdi-notes-list" style="max-height:180px;overflow-y:auto;" class="d-flex flex-column gap-2"></div>
    </div>`;

    const layout = `
    <div class="row">
        <div class="col-lg-8 mb-4 mb-lg-0">
            <div class="gdi-player-wrap rounded overflow-hidden">${playerHtml}</div>
            ${notesPanel}
        </div>
        <div class="col-lg-4">
            <div class="gdi-panel p-3">
                <h6 class="fw-bold mb-3" style="font-size:14px;"><i class="bi bi-collection-play me-2"></i>Playlist do Módulo</h6>
                <div id="gdi-playlist-list" style="max-height:450px;overflow-y:auto;" class="d-flex flex-column gap-2">
                    <div class="text-muted text-center py-3" style="font-size:12px;">Carregando playlist...</div>
                </div>
            </div>
        </div>
    </div>`;

    $("#content").html(_viewerCard('<i class="bi bi-play-circle-fill text-primary"></i>', i, t, layout, renderDownloadButtons(a)));

    setTimeout(() => {
        window._gdiPlayerInstance = document.getElementById('player');
        setupVideoProgressTracking(fileId, i, window.location.href);
        loadVideoNotes(fileId);
        loadPlaylist(window.location.pathname, a);
    }, 300);
}

function addVideoNote(videoId) {
    const input = document.getElementById('gdi-note-input');
    if (!input || !input.value.trim()) return;
    const player = window._gdiPlayerInstance;
    const currentTime = player ? player.currentTime || 0 : 0;
    
    GDIUserSystem.addNote(videoId, { text: input.value.trim(), timestamp: currentTime, formattedTime: formatTime(currentTime) });
    input.value = '';
    loadVideoNotes(videoId);
    showToast('Nota salva!');
}

function loadVideoNotes(videoId) {
    const listEl = document.getElementById('gdi-notes-list');
    if (!listEl) return;
    const notes = GDIUserSystem.getNotes(videoId);
    if (!notes.length) { listEl.innerHTML = '<div class="text-muted text-center py-2" style="font-size:12px;">Nenhuma nota ainda.</div>'; return; }
    
    listEl.innerHTML = notes.map(n => `
        <div class="p-2 rounded d-flex justify-content-between align-items-center" style="background:var(--gdi-surface-hover);border:1px solid var(--gdi-border);">
            <div><button class="badge bg-primary text-white border-0 mb-1" onclick="jumpToTimestamp(${n.timestamp})" style="cursor:pointer;"><i class="bi bi-play-fill"></i> ${n.formattedTime}</button><div style="font-size:12px;">${escHtml(n.text)}</div></div>
            <button class="btn btn-sm text-danger" onclick="deleteVideoNote('${videoId}', '${n.id}')"><i class="bi bi-trash"></i></button>
        </div>`).join('');
}

function deleteVideoNote(videoId, noteId) {
    GDIUserSystem.removeNote(videoId, noteId);
    loadVideoNotes(videoId);
}

function jumpToTimestamp(seconds) {
    const player = window._gdiPlayerInstance;
    if (player) player.currentTime = seconds;
}

function setupVideoProgressTracking(videoId, videoName, videoUrl) {
    const player = window._gdiPlayerInstance;
    if (!player) return;
    let lastSaved = 0;
    const save = () => {
        if (player.currentTime > 0 && player.duration > 0 && Math.abs(player.currentTime - lastSaved) >= 5) {
            GDIUserSystem.saveVideoProgress(videoId, { name: videoName, currentTime: player.currentTime, duration: player.duration, url: videoUrl });
            lastSaved = player.currentTime;
        }
    };
    setInterval(save, 3000);
    window.addEventListener('beforeunload', save);
}

function loadPlaylist(currentPath, currentStreamUrl) {
    const folderPath = currentPath.split("/").slice(0, -1).join("/") + "/";
    requestListPath(folderPath, {}, function(data) {
        const files = data?.data?.files || [];
        const playlistBox = document.getElementById('gdi-playlist-list');
        if (!playlistBox) return;
        
        const videos = files.filter(f => FILE_TYPES.video.includes(f.fileExtension) || f.mimeType?.includes("video"));
        if (!videos.length) { playlistBox.innerHTML = '<div class="text-muted text-center py-2" style="font-size:12px;">Nenhum outro vídeo na pasta.</div>'; return; }
        
        let html = "";
        videos.forEach(v => {
            const streamUrl = window.location.origin + v.link;
            const isCurrent = currentStreamUrl.includes(v.link);
            const style = isCurrent ? 'background:var(--gdi-primary);color:#fff;' : 'background:var(--gdi-surface-hover);';
            html += `<a href="${folderPath + encodeURIComponent(v.name)}?a=view" class="p-2 rounded text-decoration-none d-block text-truncate" style="font-size:13px;${style}" title="${escHtml(v.name)}"><i class="bi bi-play-circle me-1"></i> ${escHtml(v.name)}</a>`;
        });
        playlistBox.innerHTML = html;
    }, null);
}

// ============================================================
// MODO POMODORO FLUTUANTE COMPLETO
// ============================================================
function initPomodoroOnce() {
    if (window.__gdiPomodoroBooted) return;
    window.__gdiPomodoroBooted = true;
    
    const css = `
    #gdi-pom-root { position: fixed; bottom: 24px; right: 24px; z-index: 10000; font-family: inherit; }
    #gdi-pom-fab { width: 48px; height: 48px; border-radius: 50%; background: var(--gdi-surface); border: 1.5px solid var(--gdi-border); box-shadow: var(--gdi-shadow); cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 20px; transition: transform 0.2s; }
    #gdi-pom-fab:hover { transform: scale(1.08); }
    #gdi-pom-panel { position: absolute; bottom: 60px; right: 0; width: 240px; background: var(--gdi-surface); border: 1.5px solid var(--gdi-border); border-radius: 12px; box-shadow: var(--gdi-shadow); padding: 16px; transform: scale(0.9); opacity: 0; pointer-events: none; transition: all 0.2s; }
    #gdi-pom-panel.open { transform: scale(1); opacity: 1; pointer-events: all; }
    `;
    const styleEl = document.createElement('style'); styleEl.textContent = css; document.head.appendChild(styleEl);
    
    const root = document.createElement('div');
    root.id = 'gdi-pom-root';
    root.innerHTML = `
    <div id="gdi-pom-fab" title="Cronômetro Pomodoro">🍅</div>
    <div id="gdi-pom-panel">
      <div class="text-center fw-bold text-primary mb-2" id="gdi-pom-phase" style="font-size:11px;letter-spacing:.1em;">FOCO</div>
      <div class="text-center fw-bold mb-3" id="gdi-pom-display" style="font-size:36px;letter-spacing:.05em;">25:00</div>
      <div class="d-flex justify-content-center gap-2">
        <button class="gdi-btn gdi-btn-primary py-1 px-3" id="gdi-pom-start">Iniciar</button>
        <button class="gdi-btn gdi-btn-ghost py-1 px-2" id="gdi-pom-reset">↺</button>
      </div>
    </div>`;
    document.body.appendChild(root);
    
    let totalSecs = 1500, remainSecs = 1500, running = false, timer = null;
    const display = document.getElementById('gdi-pom-display'), startBtn = document.getElementById('gdi-pom-start');
    
    document.getElementById('gdi-pom-fab').addEventListener('click', () => {
        document.getElementById('gdi-pom-panel').classList.toggle('open');
    });
    
    function updateUI() {
        display.textContent = `${String(Math.floor(remainSecs/60)).padStart(2,'0')}:${String(remainSecs%60).padStart(2,'0')}`;
        startBtn.textContent = running ? 'Pausar' : 'Iniciar';
    }
    
    startBtn.addEventListener('click', () => {
        running = !running;
        if (running) {
            timer = setInterval(() => {
                if (remainSecs > 0) { remainSecs--; updateUI(); }
                else { clearInterval(timer); running = false; alert('Pomodoro concluído! Hora de descansar.'); remainSecs = 1500; updateUI(); }
            }, 1000);
        } else { clearInterval(timer); }
        updateUI();
    });
    
    document.getElementById('gdi-pom-reset').addEventListener('click', () => {
        clearInterval(timer); running = false; remainSecs = 1500; updateUI();
    });
}

// ============================================================
// BUSCA E INICIALIZAÇÃO FINAL
// ============================================================
function render_search_result_list() {
    const q = window.MODEL?.q || "";
    $("#content").html(`<div class="gdi-wrap"><h3 class="mb-4">Resultados para: "${escHtml(q)}"</h3><div class="gdi-panel p-4" id="search-results-box"><div class="spinner-border text-primary" role="status"></div></div></div>`);
    
    fetch(`/${window.current_drive_order || 0}:search`, { method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({q}) })
        .then(r => r.json()).then(res => {
            const files = res.data?.files || [];
            if (!files.length) { document.getElementById("search-results-box").innerHTML = '<p class="text-muted">Nenhum resultado.</p>'; return; }
            let html = '<div class="d-flex flex-column gap-2">';
            files.forEach(f => {
                html += `<div class="p-3 rounded d-flex justify-content-between align-items:center" style="background:var(--gdi-surface-hover);border:1px solid var(--gdi-border);"><div><strong>${escHtml(f.name)}</strong><br><span class="text-muted" style="font-size:11px;">${formatDateTime(f.modifiedTime)}</span></div><a href="${window.location.origin + f.link}" class="gdi-btn gdi-btn-primary" target="_blank"><i class="bi bi-eye"></i> Abrir</a></div>`;
            });
            html += '</div>'; document.getElementById("search-results-box").innerHTML = html;
        }).catch(() => { document.getElementById("search-results-box").innerHTML = '<p class="text-danger">Erro na busca.</p>'; });
}

async function getCookie(i) {
    const e = i + "="; const t = document.cookie.split(";");
    for (let n = 0; n < t.length; n++) { let a = t[n].trim(); if (a.indexOf(e) == 0) return a.substring(e.length); }
    return null;
}

window.onpopstate = () => render(window.location.pathname);

$(function() {
    init();
    GDIUserSystem.init();
    render(window.location.pathname);
    initPomodoroOnce();
});

window.toggleLessonComplete = toggleLessonComplete;
window.addVideoNote = addVideoNote;
window.deleteVideoNote = deleteVideoNote;
window.jumpToTimestamp = jumpToTimestamp;
